// 驗證 LINE Webhook 的 X-Line-Signature（HMAC-SHA256 + Base64）
// Channel Secret 由 docker-compose 的環境變數 LINE_CHANNEL_SECRET 提供，
// 不寫在工作流裡，匯出 JSON 時不會夾帶密鑰。
const crypto = require('crypto');

const item = $input.first();
const secret = $env.LINE_CHANNEL_SECRET;

if (!secret) {
  throw new Error('環境變數 LINE_CHANNEL_SECRET 未設定，無法驗證簽章');
}

// Webhook 節點開啟 Raw Body 後，原始位元組會放在 binary.data（base64）
const b64 = item.binary?.data?.data;
if (!b64) {
  throw new Error('取不到原始請求內容，請確認 Webhook 節點的 Options 已開啟 Raw Body');
}
const rawBody = Buffer.from(b64, 'base64');

const headers = item.json.headers || {};
const received = headers['x-line-signature'] || headers['X-Line-Signature'] || '';
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('base64');

// 定時比對，避免時序攻擊；長度不同時 timingSafeEqual 會丟例外，先擋掉
let valid = false;
if (received && received.length === expected.length) {
  valid = crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
}

let body = {};
try {
  body = JSON.parse(rawBody.toString('utf8'));
} catch (e) {
  valid = false;
}

return [{ json: { valid, body } }];

// 把一次 Webhook 內的多筆事件展開成多個 item，並只留下要處理的訊息事件。
// LINE 一次最多可送 100 筆事件。
const TYPE_ZH = {
  text: '文字', image: '圖片', video: '影片', audio: '音訊',
  file: '檔案', sticker: '貼圖', location: '位置',
};

// 這些字被視為閒聊，不送 AI 分類以節省費用
const TRIVIAL = new Set([
  'ok','okay','好','好的','好喔','收到','了解','瞭解','知道了','沒問題','可以',
  '感謝','謝謝','謝啦','感恩','3q','讚','棒','辛苦了','辛苦','哈囉','嗨','你好',
  '早','早安','午安','晚安','掰','再見','是','對','嗯','嗯嗯','哈哈','哈哈哈','ㄏㄏ',
]);

function needsAi(text) {
  if (!text) return false;
  // 去掉表情符號、標點與空白後再判斷長度
  const stripped = text
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, '')
    .replace(/[\s。，、．,.!！?？~～:：;；()（）\[\]「」『』-]/g, '');
  if (stripped.length < 3) return false;
  if (TRIVIAL.has(stripped.toLowerCase())) return false;
  return true;
}

const out = [];
for (const item of $input.all()) {
  const events = item.json?.body?.events || [];
  for (const ev of events) {
    // 只處理訊息事件；加入/離開群組等事件不記錄
    if (ev.type !== 'message') continue;

    const src = ev.source || {};
    // 群組、多人聊天室與一對一私訊都處理（私訊以對方的 userId 作為聊天室鍵值）
    if (src.type !== 'group' && src.type !== 'room' && src.type !== 'user') continue;

    const m = ev.message || {};
    const text = m.type === 'text' ? (m.text || '') : '';

    out.push({
      json: {
        messageId: m.id || '',
        messageType: m.type || 'unknown',
        messageTypeZh: TYPE_ZH[m.type] || '其他',
        text,
        needsAi: m.type === 'text' && needsAi(text),
        fileName: m.fileName || '',
        fileSize: m.fileSize || 0,
        contentProvider: m.contentProvider?.type || 'line',
        sourceType: src.type,
        groupId: src.groupId || src.roomId || src.userId || '',
        userId: src.userId || '',
        timestamp: ev.timestamp,
        sentAt: new Date(ev.timestamp).toISOString(),
        isRedelivery: ev.deliveryContext?.isRedelivery === true,
      },
    });
  }
}

return out;

// 官方帳號被拉進「還沒登錄」的群組時，自動在 02｜群組登錄 開一列「待確認」，
// 讓管理者知道有新群組；核准之前不記錄該群組的任何內容。
const d = $('展開訊息事件').item.json;
const summary = $('LINE｜取得群組名稱').item.json || {};
let groupName = summary.groupName || '';
if (!groupName && d.sourceType === 'user') groupName = `個人：${summary.displayName || d.userId.slice(0, 8)}`;
if (!groupName) groupName = `未命名群組 ${d.groupId.slice(-6)}`;

return {
  json: {
    ...d,
    groupName,
    notionPayload: {
      parent: { database_id: $env.NOTION_DB_GROUPS || 'e8151c00-4fdb-4496-8b04-5b91b6cc018d' },
      properties: {
        '群組名稱': { title: [{ text: { content: groupName } }] },
        '群組 ID': { rich_text: [{ text: { content: d.groupId } }] },
        '平台': { select: { name: 'LINE' } },
        '註冊狀態': { select: { name: '待確認' } },
        '註冊時間': { date: { start: d.sentAt } },
        '備註': {
          rich_text: [{
            text: {
              content: '由小助理自動偵測。核准請把「註冊狀態」改成「已登錄」並補上群組類型與所屬專案；在此之前這個群組的訊息與檔案都不會被記錄。',
            },
          }],
        },
      },
    },
  },
};

// 把「群組白名單查詢結果」「發送者名稱」與原始訊息欄位合併成後續統一使用的資料。
const base = $('展開訊息事件').item.json;

// --- 群組登錄資料（02｜群組登錄）---
const wlResults = $('Notion｜查詢群組白名單').item.json?.results || [];
const groupRow = wlResults.find((r) => r.properties?.['註冊狀態']?.select?.name === '已登錄') || wlResults[0] || {};
const gp = groupRow.properties || {};

const plain = (prop) =>
  (prop?.rich_text || prop?.title || []).map((t) => t.plain_text).join('').trim();

const groupPageId = groupRow.id || '';
const groupName = plain(gp['群組名稱']) || base.groupId;
const projectIds = (gp['所屬專案']?.relation || []).map((r) => ({ id: r.id }));
const focusHint = plain(gp['摘要重點指示']);
const groupKind = gp['群組類型']?.select?.name || '';

// --- 發送者顯示名稱（取不到時退回 LINE User ID）---
const profile = $('LINE｜取得發送者名稱').item.json || {};
const displayName = profile.displayName || (base.userId ? base.userId.slice(0, 8) : '未知成員');

// --- 台北時間字串，給檔名與 AI 判斷相對日期用 ---
const sentAtTaipei = new Date(base.timestamp).toLocaleString('sv-SE', {
  timeZone: 'Asia/Taipei',
});

return {
  json: {
    ...base,
    groupPageId,
    groupName,
    groupKind,
    projectIds,
    focusHint,
    displayName,
    sentAtTaipei,
  },
};

// 組出送給 Claude 的分類請求。要調整分類邏輯或提示詞，改這裡就好。
//
// 換模型：把 model 改成 'claude-haiku-4-5' 可大幅降低成本（約 1/5），
// 準確度略降；改成 'claude-sonnet-5' 是折衷選項。
const d = $json;

const schema = {
  type: 'object',
  properties: {
    分類: {
      type: 'string',
      enum: ['工作事項', '聯絡事項', '行事曆', '決策', '報價金額', '一般資訊'],
    },
    摘要: { type: 'string' },
    負責人: { type: 'string' },
    到期時間: { type: 'string' },
    優先級: { type: 'string', enum: ['緊急', '高', '一般', '低'] },
    信心值: { type: 'number' },
  },
  required: ['分類', '摘要', '負責人', '到期時間', '優先級', '信心值'],
  additionalProperties: false,
};

const system = [
  '你是台灣室內設計公司「川果設計 NID DESIGN LAB」的訊息分類助理。',
  '你要把 LINE 群組訊息整理成結構化紀錄，供專案週報與待辦追蹤使用。',
  '',
  '分類定義：',
  '- 工作事項：要有人去做的事，例如出圖、叫料、修改、進場、驗收。',
  '- 聯絡事項：要聯繫某人或某廠商，或交換聯絡方式。',
  '- 行事曆：有明確或可推得日期時間的會議、丈量、進場、驗收。',
  '- 決策：已拍板的選擇，例如選定material、確認尺寸、同意變更。',
  '- 報價金額：涉及價格、追加減帳、請款、付款。',
  '- 一般資訊：閒聊、回覆確認、無後續動作的說明。',
  '',
  '規則：',
  '- 摘要用繁體中文，40 字以內，寫「發生什麼事」而不是複述原文。',
  '- 負責人只填訊息中明確出現的人名或廠商名；沒有就填空字串。',
  '- 到期時間填 ISO 8601（例如 2026-08-25T10:30:00+08:00）；',
  '  只有日期沒有時間就填當天 09:00；無法判斷就填空字串。',
  '- 相對日期（明天、這週五、下週）以下方提供的「目前台北時間」為基準推算。',
  '- 優先級：有明確急迫字眼才給緊急或高，否則一般。',
  '- 信心值填 0 到 1 之間的小數，代表你對這次分類的把握。',
].join('\n');

const contextLines = [
  `目前台北時間：${d.sentAtTaipei}`,
  `群組名稱：${d.groupName}`,
  d.groupKind ? `群組類型：${d.groupKind}` : '',
  d.focusHint ? `此群組的重點提示：${d.focusHint}` : '',
  `發送者：${d.displayName}`,
  '',
  '訊息內容：',
  d.text,
].filter(Boolean).join('\n');

return {
  json: {
    ...d,
    aiRequest: {
      model: 'claude-opus-5',
      max_tokens: 1024,
      output_config: {
        effort: 'low',
        format: { type: 'json_schema', schema },
      },
      system,
      messages: [{ role: 'user', content: contextLines }],
    },
  },
};

// 解析 Claude 回傳的結構化 JSON，並組出寫入 Notion 06｜訊息紀錄 的 payload。
const d = $('整理訊息基本欄位').item.json;
const res = $json;

let ai = {};
try {
  // output_config.format 保證第一個 content block 是合法 JSON 字串
  const textBlock = (res.content || []).find((c) => c.type === 'text');
  ai = JSON.parse(textBlock.text);
} catch (e) {
  ai = {};
}

// 安全網：模型若因安全政策拒答，stop_reason 會是 refusal，此時不套用結果
if (res.stop_reason === 'refusal') ai = {};

const aiOk = Object.keys(ai).length > 0;   // AI 失敗時留待人工複核
const 分類 = ai['分類'] || '一般資訊';
const 摘要 = (ai['摘要'] || d.text || '').slice(0, 200);
const 負責人 = ai['負責人'] || '';
const 優先級 = ai['優先級'] || '一般';
const 信心值 = typeof ai['信心值'] === 'number' ? ai['信心值'] : null;

let 到期時間 = null;
const rawDue = ai['到期時間'];
if (rawDue && !Number.isNaN(Date.parse(rawDue))) 到期時間 = rawDue;

const properties = {
  '摘要': { title: [{ text: { content: 摘要 || '（空白訊息）' } }] },
  '訊息 ID': { rich_text: [{ text: { content: d.messageId } }] },
  '群組 ID': { rich_text: [{ text: { content: d.groupId } }] },
  '群組名稱': { rich_text: [{ text: { content: d.groupName || '' } }] },
  '發送者': { rich_text: [{ text: { content: d.displayName } }] },
  '發送者 ID': { rich_text: [{ text: { content: d.userId || '' } }] },
  '發送時間': { date: { start: d.sentAt, time_zone: null } },
  '訊息類型': { select: { name: d.messageTypeZh } },
  '內容': { rich_text: [{ text: { content: (d.text || '').slice(0, 2000) } }] },
  '分類': { select: { name: 分類 } },
  '優先級': { select: { name: 優先級 } },
  '負責人': { rich_text: [{ text: { content: 負責人 } }] },
  '處理狀態': { select: { name: (aiOk && 分類 === '一般資訊') ? '已處理' : '待處理' } },
};

if (信心值 !== null) properties['AI 信心值'] = { number: 信心值 };
if (到期時間) properties['到期時間'] = { date: { start: 到期時間 } };
if (d.groupPageId) properties['群組'] = { relation: [{ id: d.groupPageId }] };
if (d.projectIds?.length) properties['所屬專案'] = { relation: d.projectIds };

return {
  json: {
    ...d,
    分類,
    摘要,
    dueTime: 到期時間 || '',
    assignee: 負責人,
    priority: 優先級,
    notionPayload: {
      parent: { database_id: $env.NOTION_DB_MESSAGES || '687c5006-5421-4692-a9d9-5ff390a9c55a' },
      properties,
    },
  },
};

// 不需要 AI 分類的訊息（閒聊、貼圖、位置等）直接以預設值寫入，省下 API 費用。
const d = $json;

const 摘要 = d.messageType === 'text'
  ? (d.text || '').slice(0, 200)
  : `[${d.messageTypeZh}]`;

const properties = {
  '摘要': { title: [{ text: { content: 摘要 || '（空白訊息）' } }] },
  '訊息 ID': { rich_text: [{ text: { content: d.messageId } }] },
  '群組 ID': { rich_text: [{ text: { content: d.groupId } }] },
  '群組名稱': { rich_text: [{ text: { content: d.groupName || '' } }] },
  '發送者': { rich_text: [{ text: { content: d.displayName } }] },
  '發送者 ID': { rich_text: [{ text: { content: d.userId || '' } }] },
  '發送時間': { date: { start: d.sentAt } },
  '訊息類型': { select: { name: d.messageTypeZh } },
  '內容': { rich_text: [{ text: { content: (d.text || '').slice(0, 2000) } }] },
  '分類': { select: { name: '一般資訊' } },
  '優先級': { select: { name: '低' } },
  '處理狀態': { select: { name: '已處理' } },
};

if (d.groupPageId) properties['群組'] = { relation: [{ id: d.groupPageId }] };
if (d.projectIds?.length) properties['所屬專案'] = { relation: d.projectIds };

return {
  json: {
    ...d,
    分類: '一般資訊',
    摘要,
    notionPayload: {
      parent: { database_id: $env.NOTION_DB_MESSAGES || '687c5006-5421-4692-a9d9-5ff390a9c55a' },
      properties,
    },
  },
};

// 決定檔案在 Dropbox 的存放路徑、檔案類型與用途分類。
// 本節點以「每筆項目執行一次」模式運作，並把 binary 原封不動往下傳。
const d = $('整理訊息基本欄位').item.json;
const bin = $input.item.binary?.data || {};
const vis = $input.item.json || {};   // 影像分析結果（僅照片路徑帶入）

const ROOT = '/NIDDESIGN-LINE助理';

// Dropbox 不接受 / \ : ? * < > " | 與控制字元，開頭結尾也不能是空白或句點
const safe = (s) =>
  String(s || '')
    .split('')
    .filter((ch) => ch.charCodeAt(0) > 31)
    .join('')
    .replace(/[\/\\:?*<>"|]/g, '_')
    .replace(/^[.\s]+|[.\s]+$/g, '')
    .slice(0, 120) || '未命名';

// --- 副檔名 ---
const MIME_EXT = {
  'image/jpeg': 'jpg', 'image/png': 'png', 'image/gif': 'gif',
  'image/webp': 'webp', 'image/heic': 'heic',
  'video/mp4': 'mp4', 'video/quicktime': 'mov',
  'audio/mp4': 'm4a', 'audio/x-m4a': 'm4a', 'audio/mpeg': 'mp3',
};
const DEFAULT_EXT = { image: 'jpg', video: 'mp4', audio: 'm4a', file: 'bin' };

let originalName = d.fileName || '';
let ext = '';
if (originalName.includes('.')) {
  ext = originalName.split('.').pop().toLowerCase();
} else {
  ext = MIME_EXT[bin.mimeType] || bin.fileExtension || DEFAULT_EXT[d.messageType] || 'bin';
}

// --- 台北時間戳，用於檔名與資料夾 ---
const parts = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Taipei',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: false,
}).format(new Date(d.timestamp));            // 例：2026-08-22 14:03:51
const [datePart, timePart] = parts.split(' ');
const yearMonth = datePart.slice(0, 7);       // 2026-08
const stamp = `${datePart.replace(/-/g, '')}-${timePart.replace(/:/g, '')}`;

// --- 檔名 ---
if (!originalName) originalName = `${d.messageType}.${ext}`;
const baseName = safe(originalName.replace(/\.[^.]+$/, ''));
const fileName = `${stamp}_${safe(d.displayName)}_${baseName}.${ext}`;

// --- 群組資料夾：附上 Group ID 後 6 碼，避免同名群組互相覆蓋 ---
const groupFolder = `${safe(d.groupName)}_${d.groupId.slice(-6)}`;
const dropboxPath = `${ROOT}/${groupFolder}/${yearMonth}/${fileName}`;

// --- 檔案類型 ---
const TYPE_MAP = [
  [['jpg','jpeg','png','gif','webp','heic','heif','bmp','tif','tiff'], '照片'],
  [['mp4','mov','avi','mkv','m4v','3gp','wmv'], '影片'],
  [['m4a','mp3','wav','aac','ogg','amr'], '音訊'],
  [['pdf'], 'PDF'],
  [['dwg','dxf','dwf','rvt','rfa','skp','3ds','max','sat','step','stp','igs','iges'], 'CAD 圖檔'],
  [['xls','xlsx','xlsm','csv','numbers'], '試算表'],
  [['doc','docx','ppt','pptx','txt','rtf','pages','key','odt'], '文件'],
  [['zip','rar','7z','tar','gz'], '壓縮檔'],
];
let fileKind = '其他';
for (const [exts, name] of TYPE_MAP) {
  if (exts.includes(ext)) { fileKind = name; break; }
}

// --- 用途分類：先用檔名關鍵字猜，猜不到就留給人工 ---
const lower = originalName.toLowerCase();
const has = (...kw) => kw.some((k) => lower.includes(k));
let usage = '待分類';
if (has('報價', '估價', 'quote', 'quotation')) usage = '報價單';
else if (has('合約', '契約', 'contract', '訂單')) usage = '合約';
else if (fileKind === 'CAD 圖檔' || has('平面', '立面', '剖面', '施工圖', '圖說', '大樣')) usage = '設計圖';
else if (has('完工', '驗收', '交屋')) usage = '完工照';
else if (has('材料', '樣品', 'sample', '建材')) usage = '材料樣品';
else if (has('現場', '施工', '進度', '缺失')) usage = '施工照片';

// 照片經視覺分析時，檔名猜不出來就採用 AI 的判斷
const VALID_USAGE = ['報價單', '合約', '設計圖', '完工照', '材料樣品', '施工照片'];
if (usage === '待分類' && VALID_USAGE.includes(vis.visionUsage)) usage = vis.visionUsage;

// --- Dropbox-API-Arg 是 HTTP header，必須是純 ASCII ---
// 中文檔名要轉成 \uXXXX 逸出序列，否則 HTTP 用戶端會拒絕送出這個 header。
const asciiEscape = (s) =>
  s.split('').map((ch) => {
    const code = ch.charCodeAt(0);
    return (code >= 32 && code <= 126) ? ch : '\\u' + code.toString(16).padStart(4, '0');
  }).join('');

const dropboxApiArg = asciiEscape(JSON.stringify({
  path: dropboxPath,
  mode: 'add',
  autorename: true,      // 同名不覆蓋，自動加序號
  mute: true,
  strict_conflict: false,
}));

return {
  json: {
    ...d,
    originalFileName: originalName,
    fileName,
    ext,
    fileKind,
    usage,
    dropboxPath,
    dropboxApiArg,
    fileSizeMB: d.fileSize ? Number((d.fileSize / 1048576).toFixed(3)) : null,
    visionSummary: vis.visionSummary || '',
    visionText: vis.visionText || '',
    visionConfidence: vis.visionConfidence ?? null,
  },
  binary: $input.item.binary,    // 保留二進位內容給下一個上傳節點
};

// 整理 Dropbox 上傳與分享連結的結果，組出寫入 Notion 05｜檔案索引 的 payload。
const d = $('組出 Dropbox 路徑').item.json;
const upload = $('Dropbox｜上傳檔案').item.json || {};
const share = $json || {};

// autorename 可能改過檔名，一律以 Dropbox 實際回傳的路徑為準
const finalPath = upload.path_display || d.dropboxPath;
const finalName = upload.name || d.fileName;
const sizeMB = upload.size ? Number((upload.size / 1048576).toFixed(3)) : d.fileSizeMB;

// 分享連結正常在 .url；若連結已存在，Dropbox 會把既有連結放在錯誤內容裡
const url =
  share.url ||
  share?.error?.shared_link_already_exists?.metadata?.url ||
  '';

const backupStatus = upload.path_display ? '已備份' : '上傳失敗';

const properties = {
  '檔名': { title: [{ text: { content: finalName } }] },
  '訊息 ID': { rich_text: [{ text: { content: d.messageId } }] },
  '群組 ID': { rich_text: [{ text: { content: d.groupId } }] },
  '上傳者': { rich_text: [{ text: { content: d.displayName } }] },
  '上傳時間': { date: { start: d.sentAt } },
  '檔案類型': { select: { name: d.fileKind } },
  '用途分類': { select: { name: d.usage } },
  '副檔名': { rich_text: [{ text: { content: d.ext } }] },
  'Dropbox 路徑': { rich_text: [{ text: { content: finalPath } }] },
  '備份狀態': { select: { name: backupStatus } },
};

if (sizeMB !== null && sizeMB !== undefined) properties['檔案大小'] = { number: sizeMB };
if (url) properties['Dropbox 連結'] = { url };
if (d.groupPageId) properties['群組'] = { relation: [{ id: d.groupPageId }] };
if (d.projectIds?.length) properties['所屬專案'] = { relation: d.projectIds };

return {
  json: {
    ...d,
    finalPath,
    finalName,
    shareUrl: url,
    notionPayload: {
      parent: { database_id: $env.NOTION_DB_FILES || '32903708-fccf-48a0-b219-767da737f0ea' },
      properties,
    },
  },
};

// 附件也要在 06｜訊息紀錄 留一筆，讓群組的時間軸完整，
// 並用「關聯檔案」把這筆訊息接回 05｜檔案索引 的那一列。
const d = $('組出檔案索引').item.json;
const filePage = $json || {};

const properties = {
  '摘要': { title: [{ text: { content: d.visionSummary ? `[${d.fileKind}] ${d.visionSummary}` : `[${d.fileKind}] ${d.finalName}` } }] },
  '訊息 ID': { rich_text: [{ text: { content: d.messageId } }] },
  '群組 ID': { rich_text: [{ text: { content: d.groupId } }] },
  '群組名稱': { rich_text: [{ text: { content: d.groupName || '' } }] },
  '發送者': { rich_text: [{ text: { content: d.displayName } }] },
  '發送者 ID': { rich_text: [{ text: { content: d.userId || '' } }] },
  '發送時間': { date: { start: d.sentAt } },
  '訊息類型': { select: { name: d.messageTypeZh } },
  '內容': { rich_text: [{ text: { content: d.finalPath + (d.visionText ? `\n圖中文字：${d.visionText}` : '') } }] },
  '分類': { select: { name: d.usage === '報價單' ? '報價金額' : '一般資訊' } },
  '優先級': { select: { name: '一般' } },
  '處理狀態': { select: { name: d.usage === '待分類' ? '待處理' : '已處理' } },
};

if (d.visionConfidence !== null && d.visionConfidence !== undefined) properties['AI 信心值'] = { number: d.visionConfidence };
if (d.groupPageId) properties['群組'] = { relation: [{ id: d.groupPageId }] };
if (d.projectIds?.length) properties['所屬專案'] = { relation: d.projectIds };
if (filePage.id) properties['關聯檔案'] = { relation: [{ id: filePage.id }] };

return {
  json: {
    ...d,
    filePageId: filePage.id || '',
    notionPayload: {
      parent: { database_id: $env.NOTION_DB_MESSAGES || '687c5006-5421-4692-a9d9-5ff390a9c55a' },
      properties,
    },
  },
};

// 為照片訊息組出 Claude 視覺分析請求（base64 影像＋結構化輸出 schema）。
// 分析失敗不阻斷備份流程：任何錯誤都以 visionPayload=null 讓後續節點安全略過。
const out = [];
for (let i = 0; i < items.length; i++) {
  let payload = null;
  try {
    const mime = items[i].binary?.data?.mimeType || 'image/jpeg';
    if (mime.startsWith('image/')) {
      const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
      if (buf.length <= 4.5 * 1024 * 1024) {
        const d = $('整理訊息基本欄位').item.json;
        const context = [
          `這張照片來自室內設計公司的 LINE 聊天室「${d.groupName || '未知'}」。`,
          d.focusHint ? `此聊天室的重點：${d.focusHint}` : '',
        ].filter(Boolean).join('\n');
        payload = {
          model: 'claude-haiku-4-5',
          max_tokens: 500,
          output_config: {
            format: {
              type: 'json_schema',
              schema: {
                type: 'object',
                additionalProperties: false,
                required: ['描述', '用途分類', '圖中文字', '信心值'],
                properties: {
                  '描述': { type: 'string', description: '一句話具體描述照片內容，30字內' },
                  '用途分類': { type: 'string', enum: ['施工照片', '完工照', '材料樣品', '設計圖', '報價單', '合約', '待分類'] },
                  '圖中文字': { type: 'string', description: '照片中可辨識的重要文字（金額、圖號、品牌型號等），無則空字串' },
                  '信心值': { type: 'number' },
                },
              },
            },
          },
          messages: [{
            role: 'user',
            content: [
              { type: 'image', source: { type: 'base64', media_type: mime, data: buf.toString('base64') } },
              { type: 'text', text: `${context}\n請分析這張照片並依 schema 回傳 JSON：描述照片內容、判斷用途分類（工地施工過程選「施工照片」；完工或驗收畫面選「完工照」；建材或樣品特寫選「材料樣品」；圖面或圖紙選「設計圖」；報價或估價單據選「報價單」；合約文件選「合約」；無法判斷選「待分類」）、摘錄圖中重要文字。` },
            ],
          }],
        };
      }
    }
  } catch (e) {
    payload = null;
  }
  out.push({ json: { visionPayload: payload }, binary: items[i].binary, pairedItem: { item: i } });
}
return out;

// 解析視覺分析結果；失敗時全部留空，不影響備份。binary 從上游節點原樣取回。
const src = $('組出影像分析請求').item;
const res = $json;
let v = {};
try {
  const tb = (res.content || []).find((c) => c.type === 'text');
  v = JSON.parse(tb.text);
} catch (e) { v = {}; }
if (res.stop_reason === 'refusal') v = {};
return {
  json: {
    visionSummary: (v['描述'] || '').slice(0, 100),
    visionUsage: v['用途分類'] || '',
    visionText: (v['圖中文字'] || '').slice(0, 500),
    visionConfidence: typeof v['信心值'] === 'number' ? v['信心值'] : null,
  },
  binary: src.binary,
};
